/**
 * /components/MedicineLayout.jsx
 * ---------------------------------------------------------------------------
 * Layout cho nhóm route lồng nhau `/medicine` (xem `children` trong router).
 *
 * Component này KHÔNG render nội dung trang — nó chỉ vẽ thanh điều hướng phụ
 * rồi để <RouterView /> hiển thị route con khớp url hiện tại:
 *
 *   /medicine                     -> MedicineLayout > Medicine        (path: '')
 *   /medicine/detail/:id          -> MedicineLayout > MedicineDetail  (path: 'detail/:id')
 *   /medicine/import              -> MedicineLayout > MedicineImport  (path: '/medicine/import')
 *   /medicine/catalog             -> MedicineLayout > MedicineCatalogLayout > ...  (cấp 2, 3)
 */

import React from 'react'
import { Tabs } from 'antd'
import {
  UnorderedListOutlined,
  AppstoreOutlined,
  UploadOutlined,
} from '@ant-design/icons'

import { RouterView, useRouter, useRoute } from '@/router'
import { useI18n } from '@/lang'

/** tab -> đường dẫn tương ứng */
const TAB_PATHS = {
  list: '/medicine',
  catalog: '/medicine/catalog',
  import: '/medicine/import',
}

const MedicineLayout = () => {
  const router = useRouter()
  const route = useRoute()
  const { t } = useI18n()

  // tab đang mở: dựa vào route con khớp url hiện tại
  const activeKey = route.name?.startsWith('medicine-catalog')
    ? 'catalog'
    : route.name === 'medicine-import'
      ? 'import'
      : 'list'

  const items = [
    {
      key: 'list',
      label: (
        <span>
          <UnorderedListOutlined /> {t('Danh sách')}
        </span>
      ),
    },
    {
      key: 'catalog',
      label: (
        <span>
          <AppstoreOutlined /> {t('Danh mục')}
        </span>
      ),
    },
    {
      key: 'import',
      label: (
        <span>
          <UploadOutlined /> {t('Import Excel')}
        </span>
      ),
    },
  ]

  return (
    <>
      <Tabs
        activeKey={activeKey}
        items={items}
        onChange={(key) => router.push(TAB_PATHS[key])}
      />

      {/* chỗ hiển thị route con — tương đương <router-view /> của vue-router */}
      <RouterView />
    </>
  )
}

export default MedicineLayout
